    if (v.list === 'index') return `<div class="ix">${showProducts.slice(0, 7).map((p, i) => `<a href="#/products" data-go="products" data-reveal data-cursor="View"><span class="n">0${i + 1}</span><b>${esc(p.name)}</b><span class="mt">${esc(p.desc.slice(0, 70))}</span><span class="go">${ico('arrow')}</span></a>`).join('')}</div>`;
