    if (v.list === 'table') return `<table class="tb"><thead><tr><th>Name</th><th>Details</th><th></th></tr></thead><tbody>${showProducts.map(p => `<tr><td>${esc(p.name)}</td><td>${esc(p.desc.slice(0, 80))}</td><td style="text-align:right">${qbtn(p)}</td></tr>`).join('')}</tbody></table>`;
