  const homeProductSection = `<section class="sec hs"><div class="w">${head(c.prodK, m.hasProducts ? `Featured ${lab.toLowerCase()}` : seg.productsLabel ? `${lab} we cover` : 'What we make', m.hasProducts ? '' : c.prodS, false, v.hero !== 'wpslide')}${v.list === 'scroller' ? '' : homeProducts}<div style="margin-top:26px">${browse('line')}</div></div></section>`;

