  if (v.hero === 'diag') heroH = `<section class="hero h-diag on-dark hs"><div class="pic">${bgp(m.hero.src, 0.2)}${stockTag}</div><div class="w"><div>${kick}${h1(true)}${lead}${btns}</div></div></section><div class="tk" aria-hidden="true"><div class="tr">${[...(m.apps.length ? m.apps.map(a => a.name) : cats), ...(m.apps.length ? m.apps.map(a => a.name) : cats), ...(m.apps.length ? m.apps.map(a => a.name) : cats)].map(x => `<span>${esc(x)}</span>`).join('')}${[...(m.apps.length ? m.apps.map(a => a.name) : cats), ...(m.apps.length ? m.apps.map(a => a.name) : cats), ...(m.apps.length ? m.apps.map(a => a.name) : cats)].map(x => `<span>${esc(x)}</span>`).join('')}</div></div>`;
