  const home = heroH + boxes + (v.first === 'products' ? homeProductSection + strip + aboutBlock : strip + aboutBlock + marq + homeProductSection) + counters + (bm ? sectionsHtml(bm) : capsSection + appsSection + procBlock + stdSection + logos + quotes);

